const ZONE_GOLD_MULT = { zone1: 1.0, zone2: 1.5, zone3: 2.2, zone4: 3.5, zone5: 5.5, zone6: 9.0 };
const MYSTIC_POOL = ["anais_first","weapon_anais_first","anakim_pistols","weapon_anakim_pistols","jewel_ring_core","ring_core"];

function rollRarity(bonus = 0) {
  const r = (typeof RARITY !== 'undefined' && RARITY) ? RARITY : ((typeof window !== 'undefined' && window.GameData?.RARITY) ? window.GameData.RARITY : {
    common: { dropWeight: 70 },
    uncommon: { dropWeight: 20 },
    rare: { dropWeight: 7 },
    epic: { dropWeight: 2.5 },
    legendary: { dropWeight: 0.5 }
  });
  const rand = Math.random() * 100 - bonus;
  const legW = r.legendary?.dropWeight || 0.5;
  const epicW = r.epic?.dropWeight || 2.5;
  const rareW = r.rare?.dropWeight || 7;
  const uncW = r.uncommon?.dropWeight || 20;
  if (rand <= legW) return 'legendary';
  if (rand <= legW + epicW) return 'epic';
  if (rand <= legW + epicW + rareW) return 'rare';
  if (rand <= legW + epicW + rareW + uncW) return 'uncommon';
  return 'common';
}

function rollDrop(zoneId = 'zone1', rarityBonus = 0, isBoss = false) {
  const isLowLevel = zoneId === 'zone1' || ['talkingIsland', 'elvenForest', 'darkForest', 'orcVillage', 'dwarvenMine', 'kamaelLair', 'ruinedOutpost'].includes(zoneId);
  const equipChance = isLowLevel ? (isBoss ? 0.03 : 0.001) : (isBoss ? 0.05 : 0.003);
  if (Math.random() >= equipChance) {
    return [];
  }
  const pool = MONSTER_DROPS[zoneId] || MONSTER_DROPS.zone1;
  const itemId = pool[Math.floor(Math.random() * pool.length)];
  const rarity = rollRarity(rarityBonus);
  return [{ id: itemId, itemId, rarity, isEquipment: true, amount: 1 }];
}

function getMysticRotation() {
  return MYSTIC_POOL;
}

function rollItemWithRarity(itemId, bonus = 0) {
  const rarity = rollRarity(bonus);
  return { itemId, rarity };
}

if (typeof window !== 'undefined') {
  window.GameData = {
    ...(window.GameData || {}),
    ARMOR_SETS, ICON_MAP, RARITY, SLOT, WEAPONS, ARMORS, HELMETS, BOOTS, GLOVES, RINGS,
    LEGS, SHIELDS, BELTS, CLOAKS, SIGILS, NECKLACES, EARRINGS, HAIR, AGATHIONS,
    CONSUMABLES, MATERIALS, ALL_ITEMS, MONSTER_DROPS, SHOP_INVENTORY, CRAFTING_RECIPES,
    ZONE_GOLD_MULT, MYSTIC_POOL, rollRarity, rollDrop, getMysticRotation, rollItemWithRarity
  };
}